#!/usr/bin/env python3
# This file was generated by Claude Opus 5 for testing purposes only.
"""
PA2 Distributed Mini Discord checkpoint checker.

Usage:
    python3 tests/checkpoint_check.py
    python3 tests/checkpoint_check.py --only 0,1,2
    python3 tests/checkpoint_check.py --with-failure
    python3 tests/checkpoint_check.py --host 127.0.0.1

Run this against all three RUNNING servers (./run.sh --config servers.json).

CP0-CP10 are non-destructive and safe to run repeatedly: they create
uniquely-named users on every run and tag messages with unique text.

CP11 and CP12 require --with-failure. They will ASK YOU to terminate
Server C, and they leave the cluster in a two-process state. Restart all
three servers before the next full run.
"""

import argparse
import json
import socket
import sys
import threading
import time
import urllib.error
import urllib.parse
import urllib.request
import uuid

HOST = "127.0.0.1"
WITH_FAILURE = False

# Fixed by the PA2 specification, section 2.
SERVERS = {
    "A": {"http": 8101, "peer": 9101, "priority": 1},
    "B": {"http": 8102, "peer": 9102, "priority": 2},
    "C": {"http": 8103, "peer": 9103, "priority": 3},
}
ORDER = ["A", "B", "C"]

# channel -> (primary, backup), specification section 2.1
CHANNELS = {
    "#cs249": ("A", "B"),
    "#distributed": ("B", "C"),
    "#systems": ("C", "A"),
}

PASS, FAIL, SKIP = "PASS", "FAIL", "SKIP"
GREEN, RED, YELLOW, GREY, BOLD, RESET = (
    "\033[32m", "\033[31m", "\033[33m", "\033[90m", "\033[1m", "\033[0m"
)

results = []          # (checkpoint_number, checkpoint_name, check_name, status, detail)
_current = [0, "?"]   # checkpoint number, checkpoint name


def uniq(prefix):
    return f"{prefix}_{uuid.uuid4().hex[:6]}"


def enc(channel):
    """Percent-encode a channel name for use in a URL path."""
    return urllib.parse.quote(channel, safe="")


# ----------------------------------------------------------------- HTTP ----

class HttpResult:
    def __init__(self, status, headers, body_bytes):
        self.status = status
        self.headers = headers
        self.raw = body_bytes
        try:
            self.json = json.loads(body_bytes.decode("utf-8"))
        except Exception:
            self.json = None

    @property
    def content_type(self):
        return (self.headers.get("Content-Type") or "").lower()

    def __repr__(self):
        return f"<HTTP {self.status} {self.raw[:200]!r}>"


def http(server_id, method, path, body=None, headers=None, timeout=6):
    """Send an HTTP request to one of the three servers, by id."""
    port = SERVERS[server_id]["http"]
    url = f"http://{HOST}:{port}{path}"
    data = None
    hdrs = dict(headers or {})
    if body is not None:
        data = json.dumps(body).encode("utf-8") if not isinstance(body, bytes) else body
        hdrs.setdefault("Content-Type", "application/json")
    req = urllib.request.Request(url, data=data, headers=hdrs, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return HttpResult(r.status, r.headers, r.read())
    except urllib.error.HTTPError as e:
        return HttpResult(e.code, e.headers, e.read())
    except urllib.error.URLError as e:
        raise AssertionError(f"HTTP request to server {server_id} failed: {e.reason}")


def assert_json_ct(r):
    if "application/json" not in r.content_type:
        raise AssertionError(f"Content-Type is {r.content_type!r}, expected application/json")


def assert_status(r, expected):
    exp = expected if isinstance(expected, (list, tuple)) else [expected]
    if r.status not in exp:
        raise AssertionError(f"status {r.status}, expected {exp}; body={r.raw[:200]!r}")


def assert_error_envelope(r):
    if not (400 <= r.status < 600):
        raise AssertionError(f"expected a 4xx/5xx status, got {r.status}; body={r.raw[:200]!r}")
    if not isinstance(r.json, dict):
        raise AssertionError(f"error body is not a JSON object: {r.raw[:200]!r}")
    for k in ("status", "code", "message"):
        if k not in r.json:
            raise AssertionError(f"error object missing {k!r}: {r.json}")
    if r.json.get("status") != "error":
        raise AssertionError(f'expected "status":"error", got {r.json.get("status")!r}')


def assert_client_error(r):
    if not (400 <= r.status < 500):
        raise AssertionError(f"expected a 4xx status, got {r.status}; body={r.raw[:200]!r}")
    assert_error_envelope(r)


def field(obj, key, expected=None):
    if not isinstance(obj, dict):
        raise AssertionError(f"expected a JSON object, got {obj!r}")
    if key not in obj:
        raise AssertionError(f"missing field {key!r} in {obj}")
    if expected is not None and obj[key] != expected:
        raise AssertionError(f"{key} is {obj[key]!r}, expected {expected!r}")
    return obj[key]


# ------------------------------------------------------------ peer TCP ----

def peer_send(server_id, obj, timeout=5):
    """Open a peer connection, send one JSON line, read one JSON line back."""
    port = SERVERS[server_id]["peer"]
    try:
        sock = socket.create_connection((HOST, port), timeout=timeout)
    except OSError as e:
        raise AssertionError(f"cannot connect to server {server_id} peer port {port}: {e}")
    sock.settimeout(timeout)
    try:
        sock.sendall((json.dumps(obj) + "\n").encode("utf-8"))
        buf = b""
        while b"\n" not in buf:
            try:
                chunk = sock.recv(4096)
            except socket.timeout:
                raise AssertionError(
                    f"no peer response line from server {server_id} within {timeout}s")
            if not chunk:
                raise AssertionError(
                    f"server {server_id} closed the peer connection without responding")
            buf += chunk
        line = buf.split(b"\n", 1)[0]
        text = line.decode("utf-8", "replace").strip()
        try:
            return json.loads(text)
        except Exception:
            raise AssertionError(
                f"peer response is not valid JSON on one line: {text[:200]!r}")
    finally:
        try:
            sock.close()
        except Exception:
            pass


def port_open(port, timeout=3):
    try:
        s = socket.create_connection((HOST, port), timeout=timeout)
        s.close()
        return True
    except OSError:
        return False


# -------------------------------------------------------------- harness ----

def check(name, fn):
    try:
        fn()
        results.append((_current[0], _current[1], name, PASS, ""))
        print(f"  {GREEN}PASS{RESET}  {name}")
    except AssertionError as e:
        results.append((_current[0], _current[1], name, FAIL, str(e)))
        print(f"  {RED}FAIL{RESET}  {name}")
        print(f"        {GREY}{e}{RESET}")
    except Exception as e:
        detail = f"{type(e).__name__}: {e}"
        results.append((_current[0], _current[1], name, FAIL, detail))
        print(f"  {RED}FAIL{RESET}  {name}")
        print(f"        {GREY}{detail}{RESET}")


def skip(name, reason):
    results.append((_current[0], _current[1], name, SKIP, reason))
    print(f"  {YELLOW}SKIP{RESET}  {name}  {GREY}({reason}){RESET}")


def checkpoint(num, title):
    _current[0], _current[1] = num, title
    print(f"\n{BOLD}Checkpoint {num}: {title}{RESET}")


def make_user(server_id, prefix="u"):
    """Register a fresh user through one server and return the name."""
    name = uniq(prefix)
    r = http(server_id, "POST", "/users", {"username": name})
    if r.status != 201:
        raise AssertionError(
            f"setup: could not register {name!r} on server {server_id}: {r}")
    return name


# --------------------------------------------------------- checkpoint 0 ----

def cp0_reachable():
    checkpoint(0, "Three processes listening")
    for sid in ORDER:
        p = SERVERS[sid]["http"]
        check(f"Server {sid} HTTP port {p} accepts connections",
              lambda p=p, sid=sid: (_ for _ in ()).throw(
                  AssertionError(f"port {p} not accepting")) if not port_open(p) else None)
    for sid in ORDER:
        p = SERVERS[sid]["peer"]
        check(f"Server {sid} peer TCP port {p} accepts connections",
              lambda p=p: (_ for _ in ()).throw(
                  AssertionError(f"port {p} not accepting")) if not port_open(p) else None)


# --------------------------------------------------------- checkpoint 1 ----

def cp1_health():
    checkpoint(1, "Health endpoint reports the right server id")

    for sid in ORDER:
        def ok(sid=sid):
            r = http(sid, "GET", "/health")
            assert_status(r, 200)
            assert_json_ct(r)
            field(r.json, "status", "ok")
            field(r.json, "server_id", sid)
        check(f"GET /health on server {sid} returns status ok and server_id {sid}", ok)


# --------------------------------------------------------- checkpoint 2 ----

def cp2_peer_protocol():
    checkpoint(2, "Peer TCP heartbeat protocol")

    for sid in ORDER:
        def ping(sid=sid):
            seq = 40000 + int(uuid.uuid4().int % 10000)
            resp = peer_send(sid, {"type": "PING", "from": "TEST", "sequence": seq})
            field(resp, "type", "PONG")
            field(resp, "from", sid)
            got = field(resp, "sequence")
            if got != seq:
                raise AssertionError(f"sequence echoed as {got!r}, sent {seq!r}")
        check(f"PING to server {sid} returns PONG with a matching sequence", ping)

    def unknown_type():
        resp = peer_send("A", {"type": "NOT_A_REAL_TYPE", "from": "TEST"})
        if not isinstance(resp, dict):
            raise AssertionError(f"expected a JSON object in reply, got {resp!r}")
    check("Unknown peer message type gets a JSON reply instead of a dropped connection",
          unknown_type)

    def survives():
        resp = peer_send("A", {"type": "PING", "from": "TEST", "sequence": 1})
        field(resp, "type", "PONG")
    check("Server A peer listener still healthy after an unknown message", survives)


# --------------------------------------------------------- checkpoint 3 ----

def cp3_process_status():
    checkpoint(3, "Process status endpoint")

    for sid in ORDER:
        def status(sid=sid):
            r = http(sid, "GET", "/servers")
            assert_status(r, 200)
            assert_json_ct(r)
            rows = field(r.json, "servers")
            if not isinstance(rows, list):
                raise AssertionError(f"'servers' is not a list: {rows!r}")
            seen = {}
            for row in rows:
                seen[field(row, "server_id")] = field(row, "alive")
            for want in ORDER:
                if want not in seen:
                    raise AssertionError(f"server {want} missing from {sid}'s view: {rows}")
                if seen[want] is not True:
                    raise AssertionError(
                        f"server {sid} reports {want} as alive={seen[want]!r}, expected True")
        check(f"GET /servers on server {sid} reports all three alive", status)


