def cp4_initial_leader():
    checkpoint(4, "Initial leader is C (highest priority)")

    for sid in ORDER:
        def leader(sid=sid):
            r = http(sid, "GET", "/leader")
            assert_status(r, 200)
            assert_json_ct(r)
            field(r.json, "leader", "C")
            field(r.json, "alive", True)
        check(f"GET /leader on server {sid} reports C", leader)


# --------------------------------------------------------- checkpoint 5 ----

def cp5_user_sharing():
    checkpoint(5, "Users are shared across processes")
    a_user = uniq("alice")
    b_user = uniq("bob")

    def create_on_a():
        r = http("A", "POST", "/users", {"username": a_user})
        assert_status(r, 201)
        assert_json_ct(r)
        field(r.json, "username", a_user)
    check("POST /users on server A creates a user (201)", create_on_a)

    def create_on_b():
        r = http("B", "POST", "/users", {"username": b_user})
        assert_status(r, 201)
        field(r.json, "username", b_user)
    check("POST /users on server B creates a user (201)", create_on_b)

    for sid in ORDER:
        def visible(sid=sid):
            r = http(sid, "GET", "/users")
            assert_status(r, 200)
            users = field(r.json, "users")
            for u in (a_user, b_user):
                if u not in users:
                    raise AssertionError(
                        f"{u!r} not visible from server {sid}; got {len(users)} users")
        check(f"GET /users on server {sid} shows users created on A and B", visible)

    def duplicate_same_server():
        r = http("A", "POST", "/users", {"username": a_user})
        assert_client_error(r)
    check("Duplicate username on the same server is rejected", duplicate_same_server)

    def duplicate_other_server():
        r = http("C", "POST", "/users", {"username": a_user})
        assert_client_error(r)
    check("Duplicate username through a DIFFERENT server is rejected", duplicate_other_server)

    def bad_username():
        r = http("B", "POST", "/users", {"username": "bad name!"})
        assert_client_error(r)
    check("Invalid username characters are rejected", bad_username)

    def missing_field():
        r = http("B", "POST", "/users", {"nope": "x"})
        assert_client_error(r)
    check("Missing 'username' field is rejected", missing_field)

    def bad_json():
        r = http("C", "POST", "/users", b"{not json",
                 headers={"Content-Type": "application/json"})
        assert_client_error(r)
    check("Malformed JSON body is rejected", bad_json)


# --------------------------------------------------------- checkpoint 6 ----

def cp6_channels_and_forwarding():
    checkpoint(6, "Channel listing, membership, and request forwarding")

    for sid in ORDER:
        def listed(sid=sid):
            r = http(sid, "GET", "/channels")
            assert_status(r, 200)
            assert_json_ct(r)
            chans = field(r.json, "channels")
            for want in CHANNELS:
                if want not in chans:
                    raise AssertionError(f"{want!r} missing from server {sid}: {chans}")
        check(f"GET /channels on server {sid} lists all three fixed channels", listed)

    # #cs249 is owned by A. Join through C so the request must be forwarded.
    user = make_user("B", "fwd")

    def join_via_non_primary():
        r = http("C", "POST", f"/channels/{enc('#cs249')}/members",
                 headers={"X-User": user})
        assert_status(r, 200)
        assert_json_ct(r)
        field(r.json, "channel", "#cs249")
        field(r.json, "username", user)
        field(r.json, "joined", True)
    check("POST members for #cs249 via server C (primary is A) succeeds", join_via_non_primary)

    def members_from_primary():
        r = http("A", "GET", f"/channels/{enc('#cs249')}/users")
        assert_status(r, 200)
        field(r.json, "channel", "#cs249")
        if user not in field(r.json, "users"):
            raise AssertionError(f"{user!r} missing from the primary's member list")
    check("GET members from the primary (A) shows the forwarded join", members_from_primary)

    def members_from_third():
        r = http("B", "GET", f"/channels/{enc('#cs249')}/users")
        assert_status(r, 200)
        if user not in field(r.json, "users"):
            raise AssertionError(f"{user!r} missing from server B's member list")
    check("GET members from a third server (B) shows the same membership",
          members_from_third)

    def join_other_channels():
        # #distributed is owned by B, #systems by C: exercise the other two routes.
        r1 = http("A", "POST", f"/channels/{enc('#distributed')}/members",
                  headers={"X-User": user})
        assert_status(r1, 200)
        r2 = http("B", "POST", f"/channels/{enc('#systems')}/members",
                  headers={"X-User": user})
        assert_status(r2, 200)
    check("Joins forward correctly for #distributed (B) and #systems (C)",
          join_other_channels)

    def leave_via_non_primary():
        r = http("C", "DELETE",
                 f"/channels/{enc('#systems')}/members/{urllib.parse.quote(user)}")
        assert_status(r, 200)
        field(r.json, "channel", "#systems")
        field(r.json, "username", user)
        field(r.json, "left", True)
    check("DELETE member for #systems via server C removes the member",
          leave_via_non_primary)

    def gone():
        r = http("A", "GET", f"/channels/{enc('#systems')}/users")
        if user in field(r.json, "users"):
            raise AssertionError(f"{user!r} still listed after leaving #systems")
    check("Departed member no longer appears in #systems", gone)

    def unknown_user():
        r = http("C", "POST", f"/channels/{enc('#cs249')}/members",
                 headers={"X-User": uniq("ghost")})
        assert_client_error(r)
    check("Join by an unregistered user is rejected (error survives forwarding)",
          unknown_user)

    def no_header():
        r = http("C", "POST", f"/channels/{enc('#cs249')}/members")
        assert_client_error(r)
    check("Join without an X-User header is rejected", no_header)

    def unknown_channel():
        r = http("A", "GET", f"/channels/{enc('#nope')}/users")
        assert_client_error(r)
    check("Membership read for an unknown channel is rejected", unknown_channel)


# --------------------------------------------------------- checkpoint 7 ----

def cp7_messages():
    checkpoint(7, "Message creation and history across processes")
    sender = make_user("A", "msg")
    outsider = make_user("B", "out")
    http("C", "POST", f"/channels/{enc('#cs249')}/members", headers={"X-User": sender})

    tag = uniq("forwarded")
    state = {}

    def send_via_non_primary():
        r = http("C", "POST", f"/channels/{enc('#cs249')}/messages",
                 {"text": tag}, headers={"X-User": sender})
        assert_status(r, 201)
        assert_json_ct(r)
        field(r.json, "channel", "#cs249")
        field(r.json, "username", sender)
        field(r.json, "text", tag)
        mid = field(r.json, "message_id")
        if not isinstance(mid, int):
            raise AssertionError(f"message_id should be an integer, got {mid!r}")
        state["mid"] = mid
    check("POST message to #cs249 via server C (primary is A) returns 201",
          send_via_non_primary)

    def history_from_primary():
        r = http("A", "GET", f"/channels/{enc('#cs249')}/messages?limit=50")
        assert_status(r, 200)
        assert_json_ct(r)
        field(r.json, "channel", "#cs249")
        msgs = field(r.json, "messages")
        hit = [m for m in msgs if m.get("text") == tag]
        if not hit:
            raise AssertionError("forwarded message not present in the primary's history")
        for k in ("message_id", "username", "text"):
            if k not in hit[0]:
                raise AssertionError(f"message object missing {k!r}: {hit[0]}")
    check("GET history from the primary (A) contains the forwarded message",
          history_from_primary)

    for sid in ("B", "C"):
        def history_elsewhere(sid=sid):
            r = http(sid, "GET", f"/channels/{enc('#cs249')}/messages?limit=50")
            assert_status(r, 200)
            msgs = field(r.json, "messages")
            if not any(m.get("text") == tag for m in msgs):
                raise AssertionError(f"server {sid} history does not contain the message")
        check(f"GET history from server {sid} returns the authoritative history",
              history_elsewhere)

    def limit_param():
        for i in range(3):
            http("A", "POST", f"/channels/{enc('#cs249')}/messages",
                 {"text": f"{tag}-{i}"}, headers={"X-User": sender})
        r = http("B", "GET", f"/channels/{enc('#cs249')}/messages?limit=2")
        assert_status(r, 200)
        msgs = field(r.json, "messages")
        if len(msgs) != 2:
            raise AssertionError(f"limit=2 returned {len(msgs)} messages")
    check("?limit=N caps the history length through a non-primary", limit_param)

    def unique_ids():
        ids = []
        for i in range(5):
            r = http("C", "POST", f"/channels/{enc('#cs249')}/messages",
                     {"text": f"{tag}-u{i}"}, headers={"X-User": sender})
            ids.append(r.json.get("message_id"))
        if len(set(ids)) != len(ids):
            raise AssertionError(f"message_id values are not unique: {ids}")
    check("Sequential forwarded messages receive unique message_id values", unique_ids)

    def non_member():
        r = http("C", "POST", f"/channels/{enc('#cs249')}/messages",
                 {"text": "sneaky"}, headers={"X-User": outsider})
        assert_client_error(r)
    check("Sending without joining the channel is rejected", non_member)

    def missing_text():
        r = http("A", "POST", f"/channels/{enc('#cs249')}/messages", {},
                 headers={"X-User": sender})
        assert_client_error(r)
    check("Message without a 'text' field is rejected", missing_text)

    def unknown_channel():
        r = http("B", "POST", f"/channels/{enc('#nope')}/messages",
                 {"text": "hi"}, headers={"X-User": sender})
        assert_client_error(r)
    check("Sending to an unknown channel is rejected", unknown_channel)


# --------------------------------------------------------- checkpoint 8 ----

REPLICA_PATHS = [
    "/replica/{ch}/messages",
    "/debug/replica/{ch}/messages",
]


def _read_replica(server_id, channel):
    """Return the local replica message list, or None if no replica endpoint exists."""
    for template in REPLICA_PATHS:
        path = template.replace("{ch}", enc(channel))
        r = http(server_id, "GET", path)
        if r.status == 200 and isinstance(r.json, dict) and "messages" in r.json:
            return r.json["messages"]
    return None


def cp8_replication():
    checkpoint(8, "Message replication to the designated backup")

    probe = _read_replica("B", "#cs249")
    if probe is None:
        skip("Backup holds a local replica of a #cs249 message",
             "no local-replica endpoint found; add GET /replica/{channel}/messages")
        skip("Duplicate REPLICATE does not create a duplicate record",
             "no local-replica endpoint found")
        skip("REPLICATE_ACK has the required fields", "")
        # The ACK check does not need the endpoint, so run it anyway.
        results.pop()
        def ack_shape():
            mid = 900000 + int(uuid.uuid4().int % 90000)
            resp = peer_send("B", {
                "type": "REPLICATE",
                "channel": "#cs249",
                "message": {"message_id": mid, "username": "probe", "text": uniq("probe")},
            })
            field(resp, "type", "REPLICATE_ACK")
            field(resp, "channel", "#cs249")
            field(resp, "message_id", mid)
            field(resp, "from", "B")
        check("REPLICATE_ACK has the required fields", ack_shape)
        return

    sender = make_user("A", "rep")
    http("A", "POST", f"/channels/{enc('#cs249')}/members", headers={"X-User": sender})
    tag = uniq("replicated")

    def replicated():
        r = http("A", "POST", f"/channels/{enc('#cs249')}/messages",
                 {"text": tag}, headers={"X-User": sender})
        assert_status(r, 201)
        mid = r.json.get("message_id")
        deadline = time.time() + 6
        while time.time() < deadline:
            msgs = _read_replica("B", "#cs249") or []
            hit = [m for m in msgs if m.get("text") == tag]
            if hit:
                if hit[0].get("message_id") != mid:
                    raise AssertionError(
                        f"replica message_id is {hit[0].get('message_id')!r}, "
                        f"primary assigned {mid!r}")
                if hit[0].get("username") != sender:
                    raise AssertionError("replica username does not match the primary copy")
                return
            time.sleep(0.3)
        raise AssertionError(
            f"message {tag!r} never appeared in server B's local replica within 6s")
    check("Backup (B) stores a #cs249 message locally with the same id and contents",
          replicated)

    def ack_and_dedupe():
        mid = 900000 + int(uuid.uuid4().int % 90000)
        text = uniq("dupe")
        payload = {
            "type": "REPLICATE",
            "channel": "#cs249",
            "message": {"message_id": mid, "username": "probe", "text": text},
        }
        first = peer_send("B", payload)
        field(first, "type", "REPLICATE_ACK")
        field(first, "channel", "#cs249")
        field(first, "message_id", mid)
        field(first, "from", "B")

        second = peer_send("B", payload)
        field(second, "type", "REPLICATE_ACK")
        field(second, "message_id", mid)

        msgs = _read_replica("B", "#cs249") or []
        count = sum(1 for m in msgs if m.get("text") == text)
        if count != 1:
            raise AssertionError(
                f"after two identical REPLICATE messages the replica holds {count} copies")
    check("Duplicate REPLICATE is acknowledged but does not create a duplicate record",
          ack_and_dedupe)

    def backup_of_other_channel():
        # #distributed is owned by B and backed up by C.
        user = make_user("B", "rep2")
        http("B", "POST", f"/channels/{enc('#distributed')}/members",
             headers={"X-User": user})
        tag2 = uniq("dist")
        r = http("B", "POST", f"/channels/{enc('#distributed')}/messages",
                 {"text": tag2}, headers={"X-User": user})
        assert_status(r, 201)
        deadline = time.time() + 6
        while time.time() < deadline:
            msgs = _read_replica("C", "#distributed") or []
            if any(m.get("text") == tag2 for m in msgs):
                return
            time.sleep(0.3)
        raise AssertionError("server C never stored the #distributed replica within 6s")
    check("Backup (C) stores a #distributed message locally", backup_of_other_channel)


# --------------------------------------------------------- checkpoint 9 ----

def cp9_error_handling():
    checkpoint(9, "HTTP error handling")

    def unknown_path():
        r = http("A", "GET", "/definitely/not/a/route")
        assert_status(r, 404)
        assert_error_envelope(r)
    check("Unknown path returns 404 with an error object", unknown_path)

    def bad_method():
        r = http("B", "DELETE", "/users")
        if r.status not in (404, 405):
            raise AssertionError(f"expected 404 or 405, got {r.status}")
        assert_error_envelope(r)
    check("Unsupported method on a known path returns 404/405", bad_method)

    def invalid_channel_name():
        r = http("A", "GET", f"/channels/{enc('nohash')}/users")
        assert_client_error(r)
    check("Channel name without '#' is rejected", invalid_channel_name)

    def still_alive():
        for sid in ORDER:
            r = http(sid, "GET", "/health")
            assert_status(r, 200)
    check("All three servers still healthy after bad requests", still_alive)


# -------------------------------------------------------- checkpoint 10 ----

def cp10_concurrency():
    checkpoint(10, "Concurrency across processes")

    def concurrent_duplicate_users():
        name = uniq("race")
        statuses = []
        lock = threading.Lock()

        def worker(sid):
            try:
                r = http(sid, "POST", "/users", {"username": name})
                code = r.status
            except AssertionError as e:
                code = f"error: {e}"
            with lock:
                statuses.append(code)

        threads = [threading.Thread(target=worker, args=(sid,))
                   for sid in ORDER * 3]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        created = [s for s in statuses if s == 201]
        if len(created) != 1:
            raise AssertionError(
                f"expected exactly one 201 for {len(threads)} concurrent registrations "
                f"of the same username, got {len(created)}; statuses={statuses}")
        bad = [s for s in statuses if not isinstance(s, int) or not (400 <= s < 500 or s == 201)]
        if bad:
            raise AssertionError(f"non-4xx rejections among the losers: {bad}")
    check("Nine concurrent registrations of one username across all three servers "
          "produce exactly one 201", concurrent_duplicate_users)

    def concurrent_unique_ids():
        user = make_user("A", "conc")
        http("A", "POST", f"/channels/{enc('#cs249')}/members", headers={"X-User": user})
        ids = []
        lock = threading.Lock()

        def worker(sid):
            for i in range(4):
                r = http(sid, "POST", f"/channels/{enc('#cs249')}/messages",
                         {"text": f"conc-{sid}-{i}"}, headers={"X-User": user})
                with lock:
                    ids.append((r.status, r.json.get("message_id") if r.json else None))

        threads = [threading.Thread(target=worker, args=(sid,)) for sid in ORDER]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        statuses = {s for s, _ in ids}
        if statuses != {201}:
            raise AssertionError(f"not every concurrent send returned 201: {statuses}")
        got = [m for _, m in ids]
        if len(set(got)) != len(got):
            raise AssertionError(f"concurrent sends produced duplicate ids: {sorted(got)}")
    check("Twelve concurrent sends to #cs249 through all three servers get unique ids",
          concurrent_unique_ids)

    def heartbeats_not_blocking():
        start = time.time()
        for _ in range(10):
            r = http("C", "GET", "/health")
            assert_status(r, 200)
        elapsed = time.time() - start
        if elapsed > 5:
            raise AssertionError(
                f"ten /health calls took {elapsed:.1f}s; heartbeat work may be "
                f"blocking HTTP handling")
    check("HTTP stays responsive while heartbeats run", heartbeats_not_blocking)


# -------------------------------------------------------- checkpoint 11 ----

def cp11_failure_detection():
    checkpoint(11, "Heartbeat failure detection (Server C terminated)")

    if not WITH_FAILURE:
        skip("Failure detection checks", "re-run with --with-failure")
        return

    print(f"  {YELLOW}ACTION REQUIRED{RESET}  Terminate Server C now, without stopping A or B.")
    print(f"  {GREY}For example:  lsof -ti tcp:{SERVERS['C']['http']} | xargs kill{RESET}")
    try:
        input("  Press Enter once Server C has been terminated... ")
    except EOFError:
        skip("Failure detection checks", "no interactive terminal available")
        return

    if port_open(SERVERS["C"]["http"], timeout=2):
        skip("Failure detection checks",
             "Server C still accepting connections; it was not terminated")
        return

    def marked_down():
        deadline = time.time() + 25
        last = None
        while time.time() < deadline:
            views = {}
            for sid in ("A", "B"):
                r = http(sid, "GET", "/servers")
                rows = r.json.get("servers", []) if isinstance(r.json, dict) else []
                views[sid] = {row.get("server_id"): row.get("alive") for row in rows}
            last = views
            if all(v.get("C") is False for v in views.values()):
                return
            time.sleep(1.0)
        raise AssertionError(
            f"C still not marked unavailable 25s after termination: {last}")
    check("Servers A and B mark C unavailable within 25s", marked_down)

    def survivors_alive():
        for sid in ("A", "B"):
            r = http(sid, "GET", "/servers")
            rows = {row.get("server_id"): row.get("alive")
                    for row in r.json.get("servers", [])}
            for want in ("A", "B"):
                if rows.get(want) is not True:
                    raise AssertionError(
                        f"server {sid} reports {want} as alive={rows.get(want)!r}")
    check("Servers A and B still report each other as available", survivors_alive)

    def still_serving():
        for sid in ("A", "B"):
            r = http(sid, "GET", "/health")
            assert_status(r, 200)
        name = uniq("postkill")
        r = http("A", "POST", "/users", {"username": name})
        assert_status(r, 201)
        r2 = http("B", "GET", "/users")
        if name not in r2.json.get("users", []):
            raise AssertionError("user created after the failure is not visible on B")
    check("Surviving servers keep serving HTTP and sharing users", still_serving)

    def owned_channel_still_works():
        # #cs249 is owned by A, which is still alive: unaffected by C's death.
        user = make_user("B", "afterkill")
        r = http("B", "POST", f"/channels/{enc('#cs249')}/members",
                 headers={"X-User": user})
        assert_status(r, 200)
    check("Channels owned by surviving servers still accept writes",
          owned_channel_still_works)

    def dead_primary_is_graceful():
        # #systems is owned by C, which is gone. Any 4xx/5xx envelope is acceptable;
        # a hang or a crash is not.
        r = http("A", "GET", f"/channels/{enc('#systems')}/users", timeout=8)
        if 200 <= r.status < 300:
            return  # a cached or replicated read is acceptable
        assert_error_envelope(r)
    check("A request for a channel owned by the dead server fails cleanly, not by hanging",
          dead_primary_is_graceful)


# -------------------------------------------------------- checkpoint 12 ----

def cp12_leader_selection():
    checkpoint(12, "Leader selection after the leader fails")

    if not WITH_FAILURE:
        skip("Leader selection checks", "re-run with --with-failure")
        return

    if port_open(SERVERS["C"]["http"], timeout=2):
        skip("Leader selection checks", "Server C is still running")
        return

    def converged():
        deadline = time.time() + 25
        last = None
        while time.time() < deadline:
            seen = {}
            for sid in ("A", "B"):
                r = http(sid, "GET", "/leader")
                seen[sid] = r.json.get("leader") if isinstance(r.json, dict) else None
            last = seen
            if all(v == "B" for v in seen.values()):
                return
            time.sleep(1.0)
        raise AssertionError(
            f"surviving servers did not converge on leader B within 25s: {last}")
    check("Servers A and B both report B as the leader within 25s", converged)

    def alive_flag():
        for sid in ("A", "B"):
            r = http(sid, "GET", "/leader")
            assert_status(r, 200)
            field(r.json, "leader", "B")
            field(r.json, "alive", True)
    check("GET /leader reports leader B with alive true on both survivors", alive_flag)

    def operational_after():
        for sid in ("A", "B"):
            r = http(sid, "GET", "/health")
            assert_status(r, 200)
        r = http("A", "GET", "/channels")
        assert_status(r, 200)
    check("Both survivors remain operational after leader selection", operational_after)


# ----------------------------------------------------------------- main ----

CHECKPOINTS = [
    (0, cp0_reachable),
    (1, cp1_health),
    (2, cp2_peer_protocol),
    (3, cp3_process_status),
    (4, cp4_initial_leader),
    (5, cp5_user_sharing),
    (6, cp6_channels_and_forwarding),
    (7, cp7_messages),
    (8, cp8_replication),
    (9, cp9_error_handling),
    (10, cp10_concurrency),
    (11, cp11_failure_detection),
    (12, cp12_leader_selection),
]

NEXT_STEP = {
    0: "Get run.sh starting three processes with the ports from servers.json.",
    1: "Add GET /health returning the server's own id.",
    2: "Implement the peer TCP listener and the PING/PONG handler.",
    3: "Add the heartbeat monitor and GET /servers reporting its results.",
    4: "Add GET /leader and compute the initial leader from the fixed priorities.",
    5: "Implement user sharing: a designated owner plus a synchronous broadcast.",
    6: "Implement the channel ownership table and FORWARD for membership operations.",
    7: "Implement SEND and HISTORY, forwarding both to the channel primary.",
    8: "Implement REPLICATE/REPLICATE_ACK with dedupe, and a local-replica read endpoint.",
    9: "Add the catch-all error envelope for unknown paths and unsupported methods.",
    10: "Serialize registration at the user owner and assign message ids under the lock.",
    11: "Mark a peer unavailable after three consecutive missed heartbeats.",
    12: "Recompute the leader on availability change and send LEADER_ANNOUNCE.",
}


def main():
    global HOST, WITH_FAILURE
    p = argparse.ArgumentParser(description="PA2 Mini Discord checkpoint checker")
    p.add_argument("--host", default=HOST)
    p.add_argument("--only", default=None,
                   help="comma-separated checkpoint numbers, e.g. 1,2,3")
    p.add_argument("--with-failure", action="store_true",
                   help="run CP11/CP12, which ask you to terminate Server C")
    args = p.parse_args()

    HOST = args.host
    WITH_FAILURE = args.with_failure

    wanted = None
    if args.only:
        wanted = {int(x) for x in args.only.split(",") if x.strip()}

    print(f"{BOLD}PA2 Distributed Mini Discord checkpoint checker{RESET}")
    print(f"{GREY}target: {HOST}  "
          + "  ".join(f"{s}=http:{SERVERS[s]['http']}/peer:{SERVERS[s]['peer']}"
                      for s in ORDER)
          + f"{RESET}")

    cp0_reachable()
    if any(st == FAIL for *_, st, _ in results):
        print(f"\n{RED}Not all three processes are reachable. Start them first:{RESET}")
        print("  ./run.sh --config servers.json")
        return 2

    for num, fn in CHECKPOINTS[1:]:
        if wanted is not None and num not in wanted:
            continue
        try:
            fn()
        except Exception as e:
            _current[0] = num
            results.append((num, _current[1], "checkpoint aborted", FAIL,
                            f"{type(e).__name__}: {e}"))
            print(f"  {RED}FAIL{RESET}  checkpoint aborted: {e}")

    # -------- summary --------
    print(f"\n{BOLD}{'=' * 64}{RESET}")
    print(f"{BOLD}Summary{RESET}")
    by_cp = {}
    for num, title, name, status, detail in results:
        by_cp.setdefault((num, title), []).append((name, status, detail))

    first_incomplete = None
    for (num, title), checks in sorted(by_cp.items()):
        passed = sum(1 for _, st, _ in checks if st == PASS)
        failed = sum(1 for _, st, _ in checks if st == FAIL)
        skipped = sum(1 for _, st, _ in checks if st == SKIP)
        if failed or skipped:
            color = RED if failed else YELLOW
            if first_incomplete is None:
                first_incomplete = num
        else:
            color = GREEN
        extra = f", {skipped} skipped" if skipped else ""
        print(f"  {color}CP{num:<2}{RESET} {title:<46} {passed}/{len(checks)} passed{extra}")

    total_fail = sum(1 for *_, st, _ in results if st == FAIL)
    print()
    if total_fail == 0 and first_incomplete is None:
        print(f"{GREEN}{BOLD}All checkpoints passed. Record the demo.{RESET}")
        return 0

    print(f"{BOLD}Still to do:{RESET}")
    for num, title, name, status, detail in results:
        if status == FAIL:
            print(f"  {RED}CP{num}{RESET} {name}")
            print(f"       {GREY}{detail}{RESET}")
        elif status == SKIP:
            print(f"  {YELLOW}CP{num}{RESET} {name} {GREY}({detail}){RESET}")

    if first_incomplete is not None and first_incomplete in NEXT_STEP:
        print(f"\n{BOLD}Suggested next step:{RESET} {NEXT_STEP[first_incomplete]}")

    if WITH_FAILURE:
        print(f"\n{YELLOW}Server C was terminated during this run. "
              f"Restart all three servers before the next full run.{RESET}")
    return 1


if __name__ == "__main__":
    sys.exit(main())
